"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6348],{85424:e=>{e.exports=JSON.parse('{"functions":[{"name":"log","desc":"Logs an event. Safe to call from either realm.\\n\\nOn the client the payload is forwarded to the server and this returns\\nimmediately. On the server `data.player` is required \u2014 an event without one is\\ndiscarded.\\n\\nInvalid payloads are dropped without raising, so this never needs to be wrapped in\\na `pcall` on a hot path.","params":[{"name":"data","desc":"Event to log","lua_type":"BaseEvent"}],"returns":[],"function_type":"static","source":{"line":151,"path":"src/Shared/Class/Analytics.luau"}}],"properties":[],"types":[{"name":"BaseEvent","desc":"One analytics event. Anything failing validation \u2014 a missing event name, a\\nnegative value \u2014 is dropped silently rather than erroring.","fields":[{"name":"event","lua_type":"string","desc":"Colon-delimited event name; see the class description"},{"name":"player","lua_type":"Player?","desc":"Required on the server; filled in automatically for client calls"},{"name":"value","lua_type":"number?","desc":"Non-negative magnitude, defaults to 1"}],"source":{"line":54,"path":"src/Shared/Class/Analytics.luau"}}],"name":"Analytics","desc":"Logs custom events to Roblox\'s [AnalyticsService], from either realm.\\n\\n`LogCustomEvent` is server-only, so this module carries a RemoteEvent: a client\\ncall forwards the payload to the server, which stamps the sending player onto it\\nand logs it. The server trusts the client for the event name and value but never\\nfor the player, so a client cannot log events against someone else.\\n\\nEvent names are colon-delimited to pack extra dimensions into Roblox\'s three\\ncustom field slots. `\\"Shop:Purchase:Coins\\"` logs as event `\\"Shop\\"` with\\n`CustomField01 = \\"Purchase\\"` and `CustomField02 = \\"Coins\\"`. Segments past the\\nthird are dropped, and anything outside `[A-Za-z0-9-_. :]` becomes an underscore.\\n\\n```lua\\nAnalytics.log({ event = \\"Shop:Purchase:Coins\\", player = player, value = 250 })\\n```\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":23,"path":"src/Shared/Class/Analytics.luau"}}')}}]);